import os
os.environ['PATH'] = r'C:\Users\Administrator\miniconda3\envs\blackwell_env\Lib\site-packages\static_ffmpeg\bin\win32' + os.pathsep + os.environ['PATH']
# -*- coding: utf-8 -*- import whisper, os, sys, subprocess, json import soundfile as sf  def perform_surgical_cut():     print("\n" + "✂️"*10 + " 启动 V76 外科手术级对齐（文字锚定） " + "✂️"*10)          # 物理资产     raw_03 = r"E:\VideoTranslator_Project\temp_factory\v74_raw_2.wav"     output_03 = r"E:\VideoTranslator_Project\output_final\V76_SURGERY_SEG_03.wav"          # 1. 加载审计模型     model = whisper.load_model("base")          # 2. 执行单词级时间轴审计     # 我们不仅要文字，还要每个字的时间     print("  -> 正在定位剧本最后一个字的物理坐标...")     result = model.transcribe(raw_03, verbose=False)          # 获取最后一个 segments 的结束时间作为“语义终点”     # Whisper 的 segments 对应了剧本的结束     semantic_end = result['segments'][-1]['end'] if result['segments'] else 0          total_dur = result['segments'][-1]['end'] if result['segments'] else 0     # 我们查看波形的实际总物理长度     audio_info = subprocess.run([r"C:\Users\Administrator\miniconda3\envs\blackwell_env\Lib\site-packages\static_ffmpeg\bin\win32\ffprobe.exe", "-v", "error", "-show_entries", "format=duration", "-of", "default=noprint_wrappers=1:nokey=1", raw_03], capture_output=True, text=True)     physical_len = float(audio_info.stdout)          print(f"  🔍 审计报告：")     print(f"     - 文本结束点 (Whisper认定): {semantic_end:.2f}s")     print(f"     - 物理总长度 (模型输出): {physical_len:.2f}s")     print(f"     - 冗余幻觉长度: {physical_len - semantic_end:.2f}s (这部分极大概率就是“啊”)")      # 3. 执行精准物理切割     # 我们只保留到文字结束后的 0.05s     safe_cut = semantic_end + 0.05     FFMPEG = r"C:\Users\Administrator\miniconda3\envs\blackwell_env\Lib\site-packages\static_ffmpeg\bin\win32\ffmpeg.exe"          cmd = [         FFMPEG, "-y", "-i", raw_03,         "-af", f"atrim=end={safe_cut},asetpts=PTS-STARTPTS,afade=t=out:st={semantic_end}:d=0.05",         output_03     ]     subprocess.run(cmd, check=True, capture_output=True)     print(f"\n✅ 手术成功！已切除幻觉区域。")     print(f"📂 救治后的 03 段已保存：{output_03}")  if __name__ == "__main__":     perform_surgical_cut()
